  const layouts = sceneFacts.filter((fact) => fact.kind === "csg.web.scene.layout")
    .sort((left, right) => Number(left.routeIndex) - Number(right.routeIndex) || Number(left.nodeId) - Number(right.nodeId) || Number(left.ordinal) - Number(right.ordinal));
  const paints = sceneFacts.filter((fact) => fact.kind === "csg.web.scene.paint")
    .sort((left, right) => Number(left.routeIndex) - Number(right.routeIndex) || Number(left.nodeId) - Number(right.nodeId) || Number(left.ordinal) - Number(right.ordinal));
  const edges = sceneFacts.filter((fact) => fact.kind === "csg.web.scene.route_edge");
  const hitRects = sceneFacts.filter((fact) => fact.kind === "csg.web.scene.route_hit_rect")
    .sort((left, right) => Number(left.routeIndex) - Number(right.routeIndex) || Number(left.ordinal) - Number(right.ordinal));
  const mediaAssets = sceneMediaAssetsFromFacts(sceneFacts);
  const mediaPlaybackSlots = sceneMediaPlaybackSlotsFromFacts(sceneFacts);
  const mediaPlaybackSlotRows = sceneMediaPlaybackSlotRows(mediaPlaybackSlots, nodes);
  const mediaControlActions = sceneMediaControlActionsFromFacts(sceneFacts);
  const mediaAssetByCid = new Map(mediaAssets.map((asset) => [String(asset.assetCid ?? ""), asset]));
  const hasVideoMediaSurfaceSlot = mediaPlaybackSlotRows.some((row) =>
    Number(mediaAssetByCid.get(String(row.slot.assetCid ?? ""))?.kindCode ?? 0) === 1
  );
  const mediaSurfaceKindCodeForRow = (row) => {
    const kindCode = Number(mediaAssetByCid.get(String(row.slot.assetCid ?? ""))?.kindCode ?? 0);
    return kindCode >= 1 && kindCode <= 3 ? kindCode : 0;
  };
  const mediaSurfaceRowsForRoute = (routeIndex) => mediaPlaybackSlotRows.filter((row) =>
    Number(row.routeIndex) === Number(routeIndex) && mediaSurfaceKindCodeForRow(row) > 0
  );
  const mediaSurfaceStateMapForRoute = (routeIndex, focusRow = undefined) => {
    const stateMap = new Map();
    const setRowState = (row) => {
      const stateRef = String(row?.conditionalStateRef ?? "");
      if (stateRef.length === 0) return;
      const stateValue = sceneStateValueForCondition(row.conditionalStateValue);
      const previous = stateMap.get(stateRef);
      if (previous !== undefined && previous !== stateValue) return;
      stateMap.set(stateRef, stateValue);
    };
    setRowState(focusRow);
    for (const row of mediaSurfaceRowsForRoute(routeIndex)) setRowState(row);
    return stateMap;
  };
  const mediaSurfaceVisibleRowsForRoute = (routeIndex, stateMap) => mediaSurfaceRowsForRoute(routeIndex).filter((row) => {
    const stateRef = String(row.conditionalStateRef ?? "");
    if (stateRef.length === 0) return true;
    return stateMap.get(stateRef) === sceneStateValueForCondition(row.conditionalStateValue);
  });
  const emitMediaSurfaceStatePrep = (stateMap) => {
    for (const [stateRef, stateValue] of [...stateMap.entries()].sort((left, right) => left[0].localeCompare(right[0]))) {
      lines.push(`    if !scene.WebSceneSetStateValue(graph, ${chengString(stateRef)}, ${chengString(stateValue)}):`);
      lines.push(`        return ${code++}`);
    }
  };
