  const cssDeclarationCount = sceneCssDeclarationCount(cssVariantRules) + staticCssDeclarations.length;
  const sceneSnapshotStateRefs = collectSceneSnapshotStateRefs(sceneFacts);
  assert(routes.length > 0, "scene runtime smoke needs route facts");
  assert(layers.length > 0, "scene runtime smoke needs layer facts");
  assert(nodes.length > 0, "scene runtime smoke needs node facts");
  assert(paints.length > 0, "scene runtime smoke needs paint facts");

  const rasterResourceCount = resources.filter((resource) => Array.isArray(resource.pixels)).length;
