function scenePropValueFor(sceneFacts, routeIndex, nodeId, propName) {
  const fact = sceneFacts.find((f) => f.kind === "csg.web.scene.prop"
    && Number(f.routeIndex) === Number(routeIndex)
    && Number(f.nodeId) === Number(nodeId)
    && String(f.propName ?? "") === propName);
  return fact && typeof fact.propValue === "string" ? fact.propValue : undefined;
}

function sceneFilePickerKindFromAccept(accept) {
  const raw = String(accept ?? "").toLowerCase();
  if (raw.length === 0) return "any";
  const hasImage = raw.includes("image/");
  const hasVideo = raw.includes("video/");
  const hasAudio = raw.includes("audio/");
  const hasText = raw.includes("text/") || raw.includes("application/pdf") || raw.includes("application/epub");
  const flags = [hasImage, hasVideo, hasAudio, hasText].filter(Boolean).length;
  if (hasImage && hasVideo && flags === 2) return "image-video";
  if (hasImage && flags === 1) return "image";
  if (hasVideo && flags === 1) return "video";
  if (hasAudio && flags === 1) return "audio";
  if (hasText && flags === 1) return "text-document";
  return "any";
}

function sceneFilePickerKindForHandler(sceneFacts, eventFact, refName) {
  const directKind = scenePropValueFor(sceneFacts, eventFact.routeIndex, eventFact.nodeId, "data-csg-media-kind");
  if (directKind && /^[A-Za-z0-9_-]+$/.test(directKind)) return directKind;
  const inputRefFact = sceneFacts.find((f) => f.kind === "csg.web.scene.prop"
    && Number(f.routeIndex) === Number(eventFact.routeIndex)
    && String(f.propName ?? "") === "ref"
    && String(f.propValue ?? "") === refName);
  if (!inputRefFact) return undefined;
  const inputType = scenePropValueFor(sceneFacts, inputRefFact.routeIndex, inputRefFact.nodeId, "type");
  if (inputType !== "file") return undefined;
  return sceneFilePickerKindFromAccept(scenePropValueFor(sceneFacts, inputRefFact.routeIndex, inputRefFact.nodeId, "accept"));
}

// The same-route file-selected fact (onChange of the ref'd input) is the authoritative
// result contract (`file-selected:<ref>:<resultMode>:<resultStateRef>`). Without its two
// result segments the host picker round-trip drops the selection (Kotlin onActivityResult
// only writes back when pendingResultStateRef is non-empty), so borrow them here.
function sceneFileSelectedResultSuffixForRef(sceneFacts, routeIndex, refName) {
  const prefix = `file-selected:${refName}:`;
  for (const f of sceneFacts) {
    if (f.kind !== "csg.web.scene.event_handler" || typeof f.effect !== "string") continue;
    if (Number(f.routeIndex) !== Number(routeIndex)) continue;
    if (!f.effect.startsWith(prefix)) continue;
    const parts = f.effect.split(":");
    if (parts.length !== 4 || !parts[2] || !parts[3]) continue;
    return `:${parts[2]}:${parts[3]}`;
  }
  return "";
}

function rewriteSceneFileInputClickHandlers(sceneFacts) {
  let count = 0;
  for (const f of sceneFacts) {
    if (f.kind !== "csg.web.scene.event_handler" || typeof f.effect !== "string" || !f.effect.startsWith("invoke:")) continue;
    const handler = typeof f.handler === "string" ? f.handler.trim() : "";
    const match = /^(?:\(\s*\)|[A-Za-z_$][\w$]*|\(\s*[A-Za-z_$][\w$]*\s*\))\s*=>\s*([A-Za-z_$][\w$]*)\.current\??\.click\(\s*\)\s*;?$/.exec(handler)
      || /^([A-Za-z_$][\w$]*)\.current\??\.click\(\s*\)\s*;?$/.exec(handler);
    if (!match) continue;
    const refName = match[1];
    const kind = sceneFilePickerKindForHandler(sceneFacts, f, refName);
    if (!kind) continue;
    f.effect = `file-picker:${refName}:${kind}${sceneFileSelectedResultSuffixForRef(sceneFacts, f.routeIndex, refName)}`;
    f.actionKind = "command";
    if (f.data && f.data.action) {
      f.data.action.effect = f.effect;
      f.data.action.actionKind = "command";
    }
    count++;
  }
  return count;
}
