  const derivedValueHelpersUsed = new Map(); // helperName -> helperCode, dedup across CHT_LOCAL_DERIVED_VALUES entries
  const ownerGlobalsUsed = new Map(); // owner-keyed state global name -> {chengType, initialExpr}, merged from successful compiles
