    const readJsonTypes = new Set();
    const boxRefsUsed = new Map();   // scalar box-ref name -> chengType (KV-synced slot, not a param arg)
    const objBoxRefsUsed = new Map(); // object box-ref name -> Map(field -> chengType)
    const setBoxRefsUsed = new Map(); // set box-ref name -> elemType (mechanism 11)
    const arrBoxRefsUsed = new Map(); // array box-ref name -> {chengType, parseFn, encodeFn} (mechanism 12)
