    "        if prevOk:",
    "            if strings.SliceBytes(text, i, markerLen) == marker:",
    "                let start = i + markerLen",
    "                var end: int32",
    "                end = start",
    "                while end < textLen:",
    "                    let ch = strings.CloneStrRange(text, end, 1)",
    "                    if ch == \"\\n\" || ch == \"\\r\" || ch == \";\" || ch == \"&\":",
